import { useState } from 'react';
import { useEventLogStore, type Severity } from '@/state/useEventLogStore';
import { useViewStore } from '@/state/useViewStore';

/**
 * Section 09 §8.2 — live SCADA event / alarm log. Colour-coded by severity; each
 * entry is clickable and flies the camera to the relevant asset. Entries are
 * generated by EventLogRunner from real simulation events. Collapsible so it does
 * not crowd the HUD.
 */
const ICON: Record<Severity, string> = { info: 'ℹ', warn: '⚠', crit: '⛔' };
const STYLE: Record<Severity, { bg: string; fg: string }> = {
  info: { bg: 'rgba(60,155,209,0.14)', fg: '#bfe0f2' },
  warn: { bg: '#e0a23c22', fg: '#f2d199' },
  crit: { bg: 'rgba(189,56,97,0.18)', fg: '#f7b7c6' },
};

export function EventLog() {
  const [open, setOpen] = useState(true);
  const entries = useEventLogStore((s) => s.entries);
  const clear = useEventLogStore((s) => s.clear);
  const focusOn = useViewStore((s) => s.focusOn);

  return (
    <div className="adani-panel pointer-events-auto w-72 p-2.5 sm:w-80">
      <div className="mb-1.5 flex items-center justify-between">
        <button onClick={() => setOpen((o) => !o)} className="flex items-center gap-1.5" aria-expanded={open}>
          <span className="text-xs font-bold tracking-wide">EVENT LOG</span>
          <span className="text-[10px] text-adani-muted">{open ? '▾' : '▸'}</span>
        </button>
        <button
          onClick={clear}
          className="rounded-md bg-white/10 px-2 py-0.5 text-[10px] font-semibold text-adani-muted hover:bg-white/20 hover:text-white"
        >
          CLEAR
        </button>
      </div>
      {open && (
        <div className="flex max-h-44 flex-col gap-1 overflow-y-auto pr-1">
          {entries.length === 0 ? (
            <div className="rounded-md bg-white/[0.04] px-2 py-1.5 text-[11px] text-adani-muted">No events logged</div>
          ) : (
            entries.map((e) => {
              const st = STYLE[e.sev];
              return (
                <button
                  key={e.key}
                  onClick={() => e.focus && focusOn(e.focus.position, e.focus.target)}
                  className="flex items-start gap-1.5 rounded-md px-2 py-1 text-left text-[11px] leading-snug hover:brightness-125"
                  style={{ background: st.bg, color: st.fg, cursor: e.focus ? 'pointer' : 'default' }}
                  title={e.focus ? 'Fly to asset' : undefined}
                >
                  <span className="shrink-0 tabular-nums text-adani-muted">{e.time}</span>
                  <span aria-hidden className="shrink-0">{ICON[e.sev]}</span>
                  <span className="min-w-0">{e.text}</span>
                </button>
              );
            })
          )}
        </div>
      )}
    </div>
  );
}
